// time helpers — everything is a pure function of global time t (seconds)
const clamp = (x, a = 0, b = 1) => Math.min(b, Math.max(a, x));
const ease = x => { x = clamp(x); return x < .5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2; };
const ramp = (t, a, b) => ease((t - a) / (b - a));
const lin = (t, a, b) => clamp((t - a) / (b - a));
const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];
function el(html) { const d = document.createElement('div'); d.innerHTML = html.trim(); return d.firstElementChild; }
// fade in at a (over d), optional fade out at o
function appear(e, t, a, d = .5, dy = 24, o = null) {
  if (!e) return;
  let k = ramp(t, a, a + d);
  if (o !== null) k *= 1 - ramp(t, o, o + .4);
  e.style.opacity = k;
  e.style.transform = `translateY(${(1 - k) * dy}px)`;
}
function typeText(e, full, t, a, cps = 30) {
  const n = Math.floor(clamp((t - a) * cps, 0, full.length));
  e.textContent = full.slice(0, n);
  return n >= full.length;
}
const SCENES = [];
function scene(start, end, build, update) { SCENES.push({ start, end, build, update }); }
EOF
