const DURATION = 47;
const stage = $('#stage');
for (const s of SCENES) { s.root = el('<div class="scene"></div>'); stage.appendChild(s.root); s.build(s.root); }
// step tracker: which step is active at time t
const STEP_T = [4, 15, 24, 35, 43.5];
function render(t) {
  for (const s of SCENES) {
    const k = ramp(t, s.start, s.start + .5) * (1 - ramp(t, s.end - .5, s.end));
    s.root.style.opacity = k;
    s.root.style.display = k > 0 ? 'block' : 'none';
    if (k > 0) s.update(t - s.start, t);
  }
  const tr = $('#tracker');
  tr.style.opacity = ramp(t, 4, 4.6) * (1 - ramp(t, 43.3, 43.8));
  $$('.trk', tr).forEach((e, i) => {
    e.className = 'trk' + (t >= STEP_T[i] && t < STEP_T[i + 1] ? ' on' : t >= STEP_T[i + 1] ? ' done' : '');
  });
}
window.render = render;
window.DURATION = DURATION;
const q = new URLSearchParams(location.search);
if (q.has('t')) render(+q.get('t'));
